// Steps 3–5: GET /internal/steps/{pipeline_run_id}, retry up to 10 times with 30s between attempts.
const start = $('1. Start AI Scoring').first().json;
const baseUrl = $('Set API Base URL').first().json.baseUrl;
const pipelineRunId = start.pipeline_run_id;

if (!pipelineRunId) {
  throw new Error('Missing pipeline_run_id from Start AI Scoring response');
}

const pollUrl = `${baseUrl}/internal/steps/${pipelineRunId}`;
const maxAttempts = 10;
const waitMs = 30_000;

let last = null;
let attempt = 0;

for (attempt = 1; attempt <= maxAttempts; attempt++) {
  last = await this.helpers.httpRequest({
    method: 'GET',
    url: pollUrl,
    json: true,
  });

  if (last.done === true) {
    break;
  }

  if (attempt < maxAttempts) {
    await new Promise((resolve) => setTimeout(resolve, waitMs));
  }
}

const counts = last?.counts ?? {};

return [
  {
    json: {
      ...last,
      pipeline_run_id: pipelineRunId,
      run_id: start.run_id,
      poll_attempts: attempt,
      timed_out: last?.done !== true,
      total_tenders_scored: counts.total_tenders_scored ?? 0,
      tenders_scored: counts.tenders_scored ?? 0,
      arch_tenders_scored: counts.arch_tenders_scored ?? 0,
      commercial_tenders_scored: counts.commercial_tenders_scored ?? 0,
    },
  },
];

